import puppeteer from 'puppeteer-core';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const browser = await puppeteer.launch({headless:true, executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe', args:['--allow-file-access-from-files']});
try {
  const page = await browser.newPage();
  await page.goto(pathToFileURL(path.resolve('preview.html')).href, {waitUntil:'load'});
  await page.waitForFunction(() => window.explainer && typeof window.explainer.seek === 'function');
  const result = await page.evaluate(() => {
    const snap = (t) => {
      const s = window.explainer.seek(t);
      return {time:s.state.time, speed:s.state.speed, distance:s.state.distance};
    };
    const forwardFinal = snap(8);
    const reverseMid = snap(3);
    const reverseStart = snap(0);
    const forwardRampEnd = snap(4);
    window.explainer.setInputs({speed:6});
    const override = snap(4);
    window.explainer.clearInputs();
    const restored = snap(4);
    const slider = document.querySelector('input[type="range"]');
    const units = [...document.querySelectorAll('#stage text')].map(n => n.textContent).filter(t => /m\/s|\bm\b|s$/.test(t));
    return {forwardFinal, reverseMid, reverseStart, forwardRampEnd, override, restored, slider: slider && {min:slider.min,max:slider.max,value:slider.value}, units};
  });
  console.log(JSON.stringify(result, null, 2));
} finally { await browser.close(); }
